 public void Run(){if(running)return;t=GetComponent<MerchantTrade>();s=t.shooter;motor=t.motor;view=t.view;rate=s.rateMultiplier;oldPos=motor.transform.position;oldRot=motor.transform.rotation;oldMI=motor.InjectInput;oldSI=s.InjectInput;oldVI=view.InjectInput;oldMove=motor.TestMove;oldLook=view.TestLook;oldFire=s.TestFire;oldADS=view.TestADS;running=true;StartCoroutine(Guard());}
