 s.rateMultiplier=1;s.ResetSimulation();yield return new WaitForSeconds(.56f);yield return new WaitForEndOfFrame();ReviewCapture.Portrait(t,"portrait-load70");Check(s.ReadyVisual!=null&&s.ReadyVisual.gameObject.activeSelf,"extruding orb visible after60percent");yield return new WaitForSeconds(.5f);view.TestADS=true;yield return new WaitForSeconds(.7f);Check(view.ADS>.999f,"full ADS reached");ScreenCapture.CaptureScreenshot(D+"ads-after.png");yield return new WaitForEndOfFrame();var tip=view.lens.WorldToViewportPoint(s.hat.TipWorld);Check(Vector2.Distance(new Vector2(tip.x,tip.y),view.AimViewport)<.0001f,"ADS remains hat-tip aligned");view.TestADS=false;
 var target=FindObjectsOfType<TargetDummy>().First();int hits=target.Hits,confirm=s.GetComponent<CombatFeedback>().TargetConfirmations;Vector3 p=target.surface.bounds.center;var go=new GameObject("V09 real target probe");go.transform.position=p-Vector3.forward*2;go.AddComponent<OrbProjectile>().Launch(s.config,new OrbShotContext(go.transform.position,Vector3.forward,0,s.gameObject));yield return new WaitForSeconds(.15f);Check(target.Hits==hits+1&&s.GetComponent<CombatFeedback>().TargetConfirmations==confirm+1,"real swept target collision confirms exactly once");ScreenCapture.CaptureScreenshot(D+"target-marker.png");yield return new WaitForEndOfFrame();
