 var audio=FeedbackAudio.Instance;var box=GameObject.CreatePrimitive(PrimitiveType.Cube);box.name="Wood post diagnostic";box.transform.position=new Vector3(0,8,0);Physics.SyncTransforms();confirm=s.GetComponent<CombatFeedback>().TargetConfirmations;go=new GameObject("V09 real wood projectile");go.transform.position=new Vector3(0,8,-2);go.AddComponent<OrbProjectile>().Launch(s.config,new OrbShotContext(go.transform.position,Vector3.forward,0,s.gameObject));yield return new WaitForSeconds(.17f);Check(s.GetComponent<CombatFeedback>().TargetConfirmations==confirm,"environment collision never confirms target");Check(audio.GetComponentsInChildren<AudioSource>().Any(a=>a.clip==audio.wood&&a.spatialBlend>.6f&&Vector3.Distance(a.transform.position,new Vector3(0,8,-.5f))<.3f),"wood collision selects wood cue and spatial impact point");Destroy(box);var voices=audio.GetComponentsInChildren<AudioSource>();Check(voices.Length==8&&audio.clips.All(c=>c.loadState==AudioDataLoadState.Loaded),"eight child voices and six decoded clips loaded");var samples=new float[1024];foreach(Cue cue in Enum.GetValues(typeof(Cue))){audio.PlayCue(cue);for(int j=0;j<8;j++){yield return new WaitForSecondsRealtime(.01f);foreach(var a in voices){a.GetOutputData(samples,0);foreach(float f in samples)sourcePeak=Mathf.Max(sourcePeak,Mathf.Abs(f));}AudioListener.GetOutputData(samples,0);foreach(float f in samples)listenerPeak=Mathf.Max(listenerPeak,Mathf.Abs(f));}}Check(sourcePeak>.00001f&&listenerPeak>.00001f&&listenerPeak<.95f,"actual source and listener output nonzero with headroom");
 motor.controller.enabled=false;motor.transform.SetPositionAndRotation(new Vector3(0,.3f,-9),Quaternion.identity);motor.controller.enabled=true;typeof(ShoulderCamera).GetField("desiredYaw",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).SetValue(view,0f);yield return new WaitForSeconds(.7f);motor.TestMove=Vector2.up;motor.TestRun=true;yield return new WaitForSeconds(.3f);motor.TestSlide=true;yield return null;motor.TestSlide=false;yield return new WaitForSeconds(.1f);Check(motor.State==MoveState.Slide,"slide retained");ScreenCapture.CaptureScreenshot(D+"slide-after.png");yield return new WaitForSeconds(.9f);motor.TestRun=false;motor.TestMove=Vector2.zero;yield return new WaitForSeconds(.4f);motor.TestJump=true;yield return null;motor.TestJump=false;motor.TestJumpHeld=true;yield return new WaitForSeconds(.25f);motor.TestJump=true;yield return null;motor.TestJump=false;Check(motor.DoubleJumpUsed,"double jump retained");float until=Time.time+2;bool hover=false;while(Time.time<until){hover|=motor.State==MoveState.Hover;yield return null;}motor.TestJumpHeld=false;Check(hover,"limited glide retained");Check(runtimeErrors==0,"no runtime errors observed");}
